{
  &quot;permissions&quot;: {
     &quot;deny&quot;: [
        &quot;Read(.env*)&quot;, &quot;Read(./secrets/**)&quot;,
        &quot;WebFetch&quot;, &quot;Bash(curl *)&quot;, &quot;Bash(wget *)&quot;
     ],
     &quot;allow&quot;: [
        &quot;Bash(git *)&quot;, &quot;Bash(make build)&quot;,
        &quot;Bash(make test)&quot;, &quot;Bash(make lint)&quot;
     ],
     &quot;disableBypassPermissionsMode&quot;: &quot;disable&quot;
  },
  &quot;allowManagedPermissionRulesOnly&quot;: true,
  &quot;sandbox&quot;: {
     &quot;enabled&quot;: true,
     &quot;failIfUnavailable&quot;: true,
     &quot;allowUnsandboxedCommands&quot;: false,
     &quot;network&quot;: { &quot;allowedDomains&quot;: [&quot;git.internal.example.com&quot;,
&quot;registry.npmjs.org&quot;] },
     &quot;credentials&quot;: {
        &quot;files&quot;: [
          { &quot;path&quot;: &quot;~/.ssh&quot;, &quot;mode&quot;: &quot;deny&quot; },
          { &quot;path&quot;: &quot;~/.aws/credentials&quot;, &quot;mode&quot;: &quot;deny&quot; }
        ],
        &quot;envVars&quot;: [ { &quot;name&quot;: &quot;GITHUB_TOKEN&quot;, &quot;mode&quot;: &quot;deny&quot; } ]
     }
  },
  &quot;allowManagedHooksOnly&quot;: true,
  &quot;disableSideloadFlags&quot;: true,
  &quot;allowManagedMcpServersOnly&quot;: true,
  &quot;strictKnownMarketplaces&quot;: [
     { &quot;source&quot;: &quot;github&quot;, &quot;repo&quot;: &quot;example-corp/approved-plugins&quot; }
  ],
  &quot;requiredMinimumVersion&quot;: &quot;2.1.193&quot;
}What each line buys, in control terms<code>permissions.deny</code> keeps secrets out of the agent&#x27;s context and blocks arbitrary network egress through tools; <code>permissions.allow</code> pre-approves the safe inner loop so the deny list doesn&#x27;t turn into prompt fatigue.<code>disableBypassPermissionsMode</code> plus <code>allowManagedPermissionRulesOnly</code> means no engineer, project file or command-line flag can widen the rules.<code>sandbox</code> closes the gap permissions cannot. A tool-level deny on WebFetch doesn&#x27;t stop a shell command reaching the network; the OS-level domain allowlist blocks egress outright.<code>failIfUnavailable</code> and <code>allowUnsandboxedCommands</code> make the sandbox a gate: Claude Code refuses to start when the sandbox cannot initialize, and a command that fails inside the sandbox cannot be retried outside it.<code>credentials</code> closes the gap the deny rules leave open. <code>permissions.deny</code> governs Claude&#x27;s file tools, but a sandboxed shell command could still read <code>~/.ssh</code> or <code>~/.aws/credentials</code> by default; this block denies those reads and strips the named secrets from the environment of every sandboxed command.<code>allowManagedHooksOnly</code> means the approval gates from this play are the only hooks that run; nothing local can add to or replace them.<code>disableSideloadFlags</code> and <code>strictKnownMarketplaces</code> mean every skill, agent, hook and MCP server on an engineer&#x27;s machine arrived through the organization&#x27;s approved plugin marketplace, never from a home directory.<code>allowManagedMcpServersOnly</code> makes the agent&#x27;s tool surface an allowlist owned by the platform team.<code>requiredMinimumVersion</code> refuses to start on a version below the approved floor, so the controls are enforced by a build the organization has actually assessed.Consider the above a starting point to tailor, rather than a recommendation to copy. Every deny trades against capability, and the right balance depends on the data classification of the repo. The settings reference documents every key, including the managed-only ones: <a href="https://code.claude.com/docs/en/settings">code.claude.com/docs/en/settings</a>
